select.where:

(state in (1,2,3,4,5,6,7,11) and s.user_id = #{uid})
 and reward_name like concat('%', #{rewardName}, '%')
 and yname = #{yname}

    AND d.dept_name = #{dname}




 and reward_time = #{rewardTime}

 and user_name like concat('%', #{userName}, '%')


 and like concat('%', #{rewardJibie}, '%')
 and state = #{state}

${params.dataScope}

order  by state ,reward_time desc

mapper.select:
select #{uid} uid,s.id, u.user_name username, d.dept_name dname,p.dept_name yname,s.user_id,s.jifen,s.reward_name, s.reward_danwei, s.reward_leixing, s.reward_wenjian, s.reward_time, s.reward_fenlei, s.reward_dengji, s.reward_paiming, s.reward_jibie,s.state,
s.first_person_id, s.second_person_id, s.third_person_id, s.fourth_person_id
from sys_reward s left join sys_user u on  s.user_id= u.user_id
left join sys_dept d on u.dept_id = d.dept_id
left join sys_dept p on d.parent_id =p.dept_id
where s.user_id = #{uid} or state in (1,2)

 and yname = #{yname}
 and reward_name like concat('%', #{rewardName}, '%')
 and reward_time = #{rewardTime}
 and user_name like concat('%', #{userName}, '%')
 and state = #{state}

    AND d.dept_name = #{dname}


    AND state = #{state}

${params.dataScope}
order  by state ,reward_time desc

select #{uid} uid,s.id, u.user_name username, d.dept_name dname,p.dept_name yname,s.user_id,s.jifen,s.reward_name, s.reward_danwei, s.reward_leixing, s.reward_wenjian, s.reward_time, s.reward_fenlei, s.reward_dengji, s.reward_paiming, s.reward_jibie,s.state,
s.first_person_id, s.second_person_id, s.third_person_id, s.fourth_person_id
from sys_reward s left join sys_user u on  s.user_id= u.user_id
left join sys_dept d on u.dept_id = d.dept_id
left join sys_dept p on d.parent_id =p.dept_id
where (s.user_id = #{uid} or (state in (2,4) and d.parent_id = #{parentId}))

 and yname = #{yname}
 and reward_name like concat('%', #{rewardName}, '%')
 and reward_time = #{rewardTime}
 and user_name like concat('%', #{userName}, '%')
 and state = #{state}
 AND d.dept_name = #{dname}

order  by state ,reward_time desc

select #{uid} uid,s.id, u.user_name username, d.dept_name dname,p.dept_name yname,s.user_id,s.jifen,s.reward_name, s.reward_danwei, s.reward_leixing, s.reward_wenjian, s.reward_time, s.reward_fenlei, s.reward_dengji, s.reward_paiming, s.reward_jibie,s.state,
s.first_person_id, s.second_person_id, s.third_person_id, s.fourth_person_id
from sys_reward s left join sys_user u on  s.user_id= u.user_id
left join sys_dept d on u.dept_id = d.dept_id
left join sys_dept p on d.parent_id =p.dept_id
where s.state in (4,6)

 and yname = #{yname}
 and reward_name like concat('%', #{rewardName}, '%')
 and reward_time = #{rewardTime}
 and user_name like concat('%', #{userName}, '%')
 and state = #{state}

    AND d.dept_name = #{dname}

${params.dataScope}
order  by state ,reward_time desc

mapper.update:
UPDATE sys_reward
SET jifen = 0
WHERE id = #{id}

mapper.select:

where 1=1

    and u.user_id = #{userId}


    and u.user_name like concat('%', #{teacherName}, '%')


    and u.user_id = #{teacherId}


    and s.reward_time >= #{startTime}


    and s.reward_time <= #{endTime}


    AND d.parent_id = #{Pcollege}


    AND p.dept_id = #{college}


    AND d.dept_id = #{major}


    and u.tea_zhicheng =#{jobTitle}


    and s.reward_name like concat('%', #{topicName}, '%')


    AND s.state in (3,5,7,11)


    AND s.state in (1,2,4)


    AND s.state in (6)

order by s.reward_time desc

select p.dept_name yname, d.dept_name dname, u.login_name, u.user_name username, s.reward_name, s.jifen, s.reward_leixing, s.state, s.reward_time from sys_reward s left join sys_user u on s.user_id = u.user_id left join sys_dept d on u.dept_id = d.dept_id left join sys_dept p on d.parent_id = p.dept_id where 1=1
AND p.dept_id = #{college}
AND d.dept_id = #{major}
AND u.user_name like concat('%', #{teacherName}, '%')
and s.reward_time >= #{startTime}
and s.reward_time <= #{endTime}
and s.reward_name like concat('%', #{topicName}, '%')
AND s.state in (3,5,7,11)
AND s.state in (1,2,4)
AND s.state in (6)
AND YEAR(DATE_ADD(s.reward_time, INTERVAL 1 MONTH)) = #{year}
${_dataScope}
order by yname asc,dname asc,u.login_name asc
